            f[i].first += z * (i + 1);
            f[i].second += z * (g[j] + g[i - 1 - j]);
            f[i].second += (f[i - 1 - j].first * f[j].second + f[j].first * f[i - 1 - j].second) * C[i - 1][j] * (i + 1);
        }
